# Artificial Windows speech input for API testing; never label this physical capture.
param([string]$Ffmpeg='ffmpeg',[string]$OutputDirectory='../../work')
$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Force -Path $OutputDirectory | Out-Null
Add-Type -AssemblyName System.Speech
$speech=[System.Speech.Synthesis.SpeechSynthesizer]::new()
$wav=Join-Path (Resolve-Path $OutputDirectory).Path 'synthetic-english-speech.wav'
try {
 $speech.SetOutputToWaveFile($wav)
 $speech.Speak('Today we study aerodynamics. Lift coefficient describes the lift generated by an airfoil. The angle of attack is measured in degrees. This is a synthetic audio test for classroom translation.')
} finally {$speech.Dispose()}
& $Ffmpeg -hide_banner -loglevel error -y -i $wav -ac 1 -ar 16000 -f s16le (Join-Path $OutputDirectory 'synthetic-english-speech.pcm')
if($LASTEXITCODE -ne 0){throw 'PCM conversion failed'}
Write-Output 'Synthetic speech fixture created; not real microphone verification.'
